import{z as i,x as s,o as e,c as l,q as A,j as n,D as t,d as B,s as d,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"事件研究的微观应用","description":"","frontmatter":{"title":"事件研究的微观应用","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ed-eventstudy-micro-app.md","filePath":"quant/ed-eventstudy-micro-app.md","lastUpdated":1791063341000}'),p={name:"quant/ed-eventstudy-micro-app.md"};function u(h,E,m,c,D,C){const r=s("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="事件研究的微观应用" tabindex="-1">事件研究的微观应用 <a class="header-anchor" href="#事件研究的微观应用" aria-label="Permalink to &quot;事件研究的微观应用&quot;">​</a></h1><div class="epigraph"><p>把窗口从「日」换到「秒」，事件研究回答的问题就从「值多少钱」变成「谁在何时如何供给流动性」。</p><footer>—— 据 MacKinlay, Journal of Economic Literature, 1997；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/ed-pead-eventization">上一课</a>把漂移写成事件持仓；本课是方法落地。<a href="/quant/obd-eventstudy-micro">事件研究的微观版本</a>已立好协议——结果变量换微观量、对照加相位与共同因子控制、推断用区块自助与双重聚类；本课把协议套到第 1 至 5 课的事件谱系上，逐类给出结果变量、对照与读数含义。它做的是应用：协议不重推，谱系外的新类型暂不涉及。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日频事件研究把两个问题合成一个数：价格发现快不快，水平被推高多少。微观口径把二者拆开，而<strong>每类事件拆开后的形状不同</strong>：宏观发布跳得快、回吐快，财报隔夜的定价误差集中在开盘竞价，指数调整的冲击压在生效日拍卖，期权到期改变尾盘方差，制度变化移动速率系数。用同一个「公告日异常收益」度量这五种机制，得到的既不是价格发现也不是水平，而是加权平均——缺口因此是逐类的设计表。</p><p><span class="marginnote">术语翻译：「结果变量」就是把被测量的东西从收益率换成微观量，如开盘 30 分钟价差、撤单率；「对照」是选一个除事件外一切相似的基准（同股非公告开盘、同分钟无发布日）。两者相减，剩下的才是事件留下的净痕迹。</span></p><h3 id="设计表" tabindex="-1">设计表 <a class="header-anchor" href="#设计表" aria-label="Permalink to &quot;设计表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>结果变量</th><th>对照</th></tr></thead><tbody><tr><td>财报</td><td>开盘 30 分钟收益、价差、定价误差</td><td>同股非公告开盘相位</td></tr><tr><td>指数调整</td><td>拍卖成交占比、冲击系数、生效后回吐比</td><td>平静日收盘拍卖</td></tr><tr><td>期权到期</td><td>尾盘收益方差、收盘价聚集频率</td><td>非到期同相位</td></tr><tr><td>宏观发布</td><td>跳完成时间、价差峰值与回落半衰</td><td>无发布日同分钟</td></tr><tr><td>制度变化</td><td>撤单率、深度、费率敏感性等系数</td><td>不受影响品种同窗</td></tr></tbody></table><p>指数调整与宏观两行的对照时点，用<a href="/quant/close-auction-imbalance">收盘竞价不平衡</a>与实时快照口径：<strong>用事件当时已公布的量，不用事后重组的量</strong>——微观研究最大的自欺都从时点错配进来。</p><p><span class="marginnote">财报隔夜的反应主要落在开盘集合竞价与头三十分钟；把「次日收盘」当公告反应，会把公告跳与漂移首段混在一起——第 1 课的窗口纪律在秒级上以更高分辨率复现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>先画事件前形状。</strong> 微观量有强日内季节性与体制依赖：「事件后 vs 事件前」的比较都要先确认事件前相位是基线；形状搬家日（半日市、规则过渡日）先剔除。</p><p><strong>推断按微观数据的现实来。</strong> 序列相关与横截面相关都强：区块自助或双重聚类是底线配置；单次事件功效天然弱，靠机制证据累积——系数变化的方向与幅度是否与通道预测一致，比显著性检验更有分量。</p><p><strong>输出是速率表，不是评分卡。</strong> 每类事件产出一行：价格发现完成时间、流动性摆动的幅度与半衰、对冲流符号。读数直接服务前几课的交易设计：财报的执行窗、调仓生效日的参与上限、到期尾盘的风险预算。微观表是参数来源，非打分卡。</p>',14)),(e(),n(o,null,{default:t(()=>[d(r,{id:"mermaid-109",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E4%BA%8B%E4%BB%B6%E8%B0%B1%E7%B3%BB%EF%BC%9A%E8%B4%A2%E6%8A%A5%20%E8%B0%83%E6%95%B4%20%E5%88%B0%E6%9C%9F%20%E5%AE%8F%E8%A7%82%20%E5%88%B6%E5%BA%A6%22%5D%20--%3E%20BASE%5B%22%E4%BA%8B%E4%BB%B6%E5%89%8D%E7%9B%B8%E4%BD%8D%E5%BD%A2%E7%8A%B6%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20BASE%20--%3E%20RV%5B%22%E7%BB%93%E6%9E%9C%E5%8F%98%E9%87%8F%EF%BC%9A%E9%80%9F%E7%8E%87%E4%B8%8E%E6%B5%81%E5%8A%A8%E6%80%A7%E9%87%8F%22%5D%0A%20%20RV%20--%3E%20CTRL%5B%22%E5%AF%B9%E7%85%A7%EF%BC%9A%E5%90%8C%E7%9B%B8%E4%BD%8D%20%E5%90%8C%E5%93%81%E7%A7%8D%20%E5%90%8C%E7%AA%97%22%5D%0A%20%20CTRL%20--%3E%20INF%5B%22%E6%8E%A8%E6%96%AD%EF%BC%9A%E5%8C%BA%E5%9D%97%E8%87%AA%E5%8A%A9%20%E5%8F%8C%E9%87%8D%E8%81%9A%E7%B1%BB%22%5D%0A%20%20INF%20--%3E%20OUT%5B%22%E9%80%9F%E7%8E%87%E7%B3%BB%E6%95%B0%E8%A1%A8%EF%BC%9A%E6%9C%8D%E5%8A%A1%E6%89%A7%E8%A1%8C%E4%B8%8E%E9%A3%8E%E6%8E%A7%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"微观口径为什么能改写结论：事件风险的承担者是流动性供给者，价差与深度的时序就是风险补偿的合同条款。宏观发布前价差加宽、后一两分钟恢复——补偿峰值在定价完成之前；财报隔夜的定价误差集中在开盘释放——补偿集中在竞价深度；到期尾盘方差被压扁——补偿是负的（对冲反而轻松）。同一张日频收益表下藏着五种不同的补偿结构；执行与风控参数应从补偿结构里读出，而不是从收益平均值里猜。这也是本课放在风控之前的原因：前五课立对象，第 6 课立持仓，本课立测量，第 8 课的风控才有数可看。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：把流动性供给者想成汛期摆渡的船夫。洪水（宏观发布）来临前先抬价，水退就降价；财报日像定时涨潮，船夫把大船提前泊在竞价码头；到期尾盘反而风平浪静，摆渡近乎免费。补偿各有各的「时间表」，速率表记录的就是它。")],-1)),(e(),n(o,null,{default:t(()=>[d(r,{id:"mermaid-119",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E5%BC%A0%E6%97%A5%E9%A2%91%E6%94%B6%E7%9B%8A%E8%A1%A8%E4%B8%8B%3A%20%E8%A1%A5%E5%81%BF%E7%BB%93%E6%9E%84%E9%95%BF%E4%BB%80%E4%B9%88%E6%A0%B7%3F%22%5D%0A%20%20Q%20--%3E%20M%5B%22%E5%AE%8F%E8%A7%82%3A%20%E4%BB%B7%E5%B7%AE%E5%B3%B0%E5%80%BC%E5%9C%A8%E8%B7%B3%E5%AE%8C%E6%88%90%E4%B9%8B%E5%89%8D%20%E9%9A%8F%E5%90%8E%E5%9B%9E%E8%90%BD%22%5D%0A%20%20Q%20--%3E%20E%5B%22%E8%B4%A2%E6%8A%A5%3A%20%E8%A1%A5%E5%81%BF%E9%9B%86%E4%B8%AD%E5%9C%A8%E5%BC%80%E7%9B%98%E7%AB%9E%E4%BB%B7%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20Q%20--%3E%20X%5B%22%E5%88%B0%E6%9C%9F%3A%20%E8%A1%A5%E5%81%BF%E4%B8%BA%E8%B4%9F%20%E5%B0%BE%E7%9B%98%E6%96%B9%E5%B7%AE%E8%A2%AB%E5%8E%8B%E6%89%81%22%5D%0A%20%20Q%20--%3E%20I%5B%22%E8%B0%83%E6%95%B4%3A%20%E5%86%B2%E5%87%BB%E5%8E%8B%E5%9C%A8%E7%94%9F%E6%95%88%E6%97%A5%E6%94%B6%E7%9B%98%E6%8B%8D%E5%8D%96%22%5D%0A%20%20M%20--%3E%20OUT%5B%22%E8%AF%BB%E5%87%BA%E6%89%A7%E8%A1%8C%E4%B8%8E%E9%A3%8E%E6%8E%A7%E5%8F%82%E6%95%B0%22%5D%0A%20%20E%20--%3E%20OUT%0A%20%20X%20--%3E%20OUT%0A%20%20I%20--%3E%20OUT%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>时间戳与快照纪律决定一切：公布时点快照、时标对齐、盘后归属，任何错配都会让速率表变成噪声表。跨市场要重校准：同样的事件在不同做市结构与竞价制度下速率形状不同，表不可直接搬运。单事件结论只做描述不进参数；参数靠多事件截面累积。微观表回答「机制是什么」，不回答「该不该做」——后者需要成本模型与容量分析，是执行侧的账。</p><p><span class="marginnote">常见误区：拿一次事件的速率表直接去定参数。单次事件功效天然弱，快照错一秒、口径错一档，表就成噪声；参数要靠多事件截面积累，并用机制形状（方向、半衰、符号）反复核对，而不是靠一次漂亮的读数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逐类设计：结果变量换微观量、对照对齐相位与品种、推断防序列与横截面相关。</li><li>先画事件前形状基线，形状搬家日剔除；快照口径用事件当时已公布的量。</li><li>微观表把日频异常收益拆成价格发现速度与补偿结构，分别服务执行与风控。</li><li>单事件只做描述；参数靠多事件截面与机制形状核对累积。</li><li>出处：MacKinlay, <em>Journal of Economic Literature</em>, 1997；协议见<a href="/quant/obd-eventstudy-micro">事件研究的微观版本</a>；快照口径见<a href="/quant/close-auction-imbalance">收盘竞价不平衡</a>；Harris, <em>Trading and Exchanges</em>, 2003。</li></ul>',5))])}const b=i(p,[["render",u]]);export{F as __pageData,b as default};
